                    [0x29582d73906f8c40UL] = "Pero la lucha entre el Orden y el Caos aún no está decidida. La balanza se inclinará y nuestros héroes volverán una y otra vez a Ciudad Soleada.",
                    [0x29b4fe2dbb57ef6aUL] = "¡¡¡MI VIDA POR BALISTAAAAA!!!",
