                    [0x40fedf513f4bf84fUL] = "BLOQUE DE DETENCIÓN A",
                    [0x431202ac48344bf4UL] = "¡Esta noche solo hay una ley: ¡Haz lo que tu Odio te diga!",
                    [0x43f92a5c402137ddUL] = "¡Demasiados... demasiados!",
                    [0x44cc3f3f7d3fe1e0UL] = "Al menos la electricidad ha vuelto... pero ¿qué demonios pasa con las cámaras de seguridad?",
                    [0x45112e69a0ede541UL] = "Hay un piloto, prisionero como vosotros, en el Bloque D. Si alguien puede sacaros de aquí, es él. Yo os llevo hasta él, pero primero ayudadme a matar a Balista.",
                    [0x46633bc8a3feeadaUL] = "¡Maldita sea! Algo va mal con loh motoreh. ¿Qué zoquete trabajó en ehtoh? Dadme un minuto para mirar bajo el capó...",
                    [0x4777cc942d9250faUL] = "Puedes decirles a tus hombres que se relajen, detective. Nosotros nos encargamos.",
                    [0x48f915a5bbed5545UL] = "Ruido extraño... Lo ignoraré.",
                    [0x4cc55697b6b10e11UL] = "¡No os libraréis de mí tan fácilmente, amantes de los cerdos!",
                    [0x4cdedc0731675745UL] = "¡No es ESE el punto! ¡Se trata de... de PRINCIPIOS! ¿Dónde estaría la Pandilla Colmena si empezáramos a PAGAR por las cosas?",
