                    [0x4e52106b24fc9771UL] = "Vale, me habéih convencido. ¡Vamoh a salir volando de aquí!",
                    [0x4fea2fa39f3b3823UL] = "¡Se lo merecen! No sé qué trama McBride, pero es buen policía. No quedamos muchos en esta ciudad...",
                    [0x52a5a79ed1d29c03UL] = "Muchos han señalado los eventos de esta noche como prueba de la obsolescencia de la fuerza policial tradicional, y que la aplicación de la ley totalmente privatizada es sin duda el camino del futuro.",
                    [0x5391db195f195110UL] = "¡Una huida shsuave, teniendo en cuenta todo!",
                    [0x54b686163fa4490fUL] = "¡RUHAHAAAARRR HUARRRR!",
                    [0x5954a097af2969f2UL] = "...¡¡¡EMERGENCIA!!! ¡Abandonad la nave!",
                    [0x5a7b270b6fc84783UL] = "Gracias por la ayuda. Será mejor que salgáis de aquí. Lejos de Ciudad Soleada.",
                    [0x5dc60337c07f4fe1UL] = "Ciudad Soleada, 20XX\r\n\r\nComisaría 9ª",
