                    [0x620282fb56b61254UL] = "Oooh... No sé, eso suena a mucho trabajo... Más fácil simplemente...",
                    [0x65d92816d864926eUL] = "¡A todos mis valientes guerreros, mis fieles berserkers: aplastad los últimos focos de resistencia! ¡Traedme la cabeza del Comisario Hagan!",
                    [0x66d57fd83ba780ceUL] = "¡Se acabó! ¡NADIE va a entrar! ¡No importa cuánto SUPLIQUEN!",
                    [0x6b2c32be2d6e8929UL] = "¡Matad también a los prisioneros! ¡Ya tenemos todos los guerreros que necesitamos!",
                    [0x6d1da39229b50eb2UL] = "Has oído a la dama, madero. ¡Hora de decir buenas noches!",
                    [0x6e2d3cb39ba594cbUL] = "¡BASTARDOS! ¡No os saldréis con la vuestra!",
                    [0x6f48c5680a6578a8UL] = "¡Mueve tu culo!",
                    [0x6ffcc22b3a80afd2UL] = "¡Socorro! ¡Va a por mí!",
                    [0x7032c1ee00e8c277UL] = "Jeff",
                    [0x70818f5012b2a6b9UL] = "Vale, veamoh aquí. Preferiría mi fiel avión, pero... ehtoh servirá. Shi puedo encontrar el contacto. Ah, aquí ehtá.",
                    [0x70897260e656a02cUL] = "BLOQUE",
                    [0x72a8dd799de66b83UL] = "SALIDA",
                    [0x74d1004c33a4cf82UL] = "Ehta coha eh vieja incluho para mí... ¿Dónde va ehta pieza? No, ahsí no eh...",
                    [0x76593c4f11889014UL] = "Quiero decir, ¿qué shentido tiene shi pueden simplemente... hmm... umm... eh eho un...?",
                    [0x76bae89ee56047a0UL] = "¡Dios nos salve, es la Pandilla Colmena!",
                    [0x794b42e6e43d51acUL] = "Nel.",
                    [0x80dc943a46520f6cUL] = "¡Eh, jefe! ¡Quiero mi llamada!",
                    [0x87ee43f95113b100UL] = "MATAD\r\n  A TODOS\r\nLOS POLIS",
                    [0x8ac3573c90cfbc94UL] = "¿Así que pondrás a mis propios hombres en mi contra?! ¡Maldita, apestosa, sedienta de sangre...",
                    [0x8b374962aea1e30eUL] = "¡Ja! ¡Ni hablar!",
                    [0x8b3bc239dedf1bc0UL] = "¡Mierda, vienen! Escuchad. Hay un ascensor tras la puerta detrás de vosotros. Intentaré encontrar otro camino arriba. Nos vemos allí, eso espero.",
                    [0x8b3bd9f00d1c3605UL] = "¡No! ¿Cómo habéis entrado? ¡AYUDA!!",
                    [0x8b8b89dc8de8ecf6UL] = "Mátalos.",
                    [0x8bb41de9553af736UL] = "Hasta entonces, qué decir salvo:\r\nBien jugado, damas y caballeros.",
                    [0x8e781aceec208dfeUL] = "Aquí Balista. Esta comisaría está ahora bajo control de la Pandilla Colmena. Todas las salidas están selladas. No hay escape.",
                    [0x8eb45aba1a7af43fUL] = "...con más nieve esperada durante el fin de semana festivo.",
                    [0x8eda0d484d2b9b1aUL] = "¡Guárdate las excusas para el jefe, idiota!",
