                    [0x921185c061452504UL] = "¡Muere! ¡Por orden de Balista!",
                    [0x9445dc6be5a3ee7dUL] = "No sé. Quería interrogarlos o algo. O quizá solo quería fastidiar a esos babosos corporativos.",
                    [0x993a2f48484a41e2UL] = "¡OYE! ¿No tenéis ningún respeto por la ley y el orden!?",
                    [0xa3e0bd0a4c2d32faUL] = "¡Tú... tú... por qué debería...!",
