                    [0xafae86a2590e4b00UL] = "¿Me enviáis una postal, vale?",
                    [0xafc7d444ab3a616bUL] = "Shi buhcáis mi cerveza, ya no queda. Ehtoh maderoh me la confih... quitaron cuando me detuvieron. ¡Me quitaron lah alah, loh bahtardoh!",
                    [0xb212b8ea4802f71aUL] = "¡DERROTA\r\nEl piloto murió!",
                    [0xb7d3d2d176763a19UL] = "Por cierto, me llamo Jeff. ¿Sabes? Ehto podría ser el comienzo de algo hermoho...",
                    [0xbb5a28cd54f65e38UL] = "Esta emisión ha sido patrocinada por MetroCorp: Un Futuro Más Brillante para Ciudad Soleada. ¡Buenas noches!",
                    [0xbb6a540c1ec0e4f4UL] = "¡El ejército de matones fanáticos de Balista tomó rápidamente el control de la comisaría y se ha atrincherado dentro! ¡No está claro si alguien sobrevivió al bárbaro ataque!",
                    [0xbcb3cc0bf22360bdUL] = "¡Aquí Balista! ¡El cobarde de Hagan debe entregarse!",
                    [0xbce92351bca42cf8UL] = "El alcalde considera que su departamento... es INSUFICIENTE para la situación. Deje esto a los profesionales.",
                    [0xbd1b53ade13daa4dUL] = "¡Entretenedlos mientrah trabajo en ehtoh!",
                    [0xbdd49e2f3d6dd1d1UL] = "Ahora, imagino que toca descansar. Un momento de paz, quizá, en algún lugar más allá de esas colinas oscuras.",
                    [0xc09bbd3d2f3fdbccUL] = "¡Escoria mercenaria! ¡Pedí refuerzos, POLIS, no un montón de mercenarios gatillo fácil!",
                    [0xc232981f08e5d7beUL] = "Sé eso PERFECTAMENTE, detective. Buenas noches.",
                    [0xc2df6869edc67547UL] = "MÁTALOS\r\nA\r\nTODOS",
                    [0xc5ad69595973c5cbUL] = "ANARQUÍA",
                    [0xc74a88131e6a22dfUL] = "Hmmm. Primer motor lihto, pero el hegundo podría necehitar unoh retoqueh máh. ¡Entretenedloh un poco máh, chicoh!",
                    [0xc8dea6adab5b0254UL] = "OBEDECE",
                    [0xc96a323fc267e0feUL] = "¡Venga, salgamos de aquí!",
                    [0xcd2a719214a4f9b6UL] = "Balista",
                    [0xcf18e1924041e938UL] = "Quiero todas las salidas selladas. Nadie entra ni sale. Voy a hacerle una visita al Comisario.",
                    [0xd0c865f0a840ceb5UL] = "SIN\r\nPIEDAD",
                    [0xd0ed97895f85a908UL] = "¿Como qué? Ya les estamos disparando. Y nos hemos quedado sin BarreCalles.",
                    [0xd234a886d21a0080UL] = "¡Ríndete, Balista! ¡Hagan está muerto, ya tienes lo que querías!",
                    [0xd844e8b6c449a9dfUL] = "Alfa tango a zeta foxtrot. Desplieguen a los BarreCalles.",
                    [0xdab28176b0d9658fUL] = "¡MANDA!",
                    [0xdb046f5df26c80aeUL] = "El asalto fue una venganza imprudente por la reciente campaña contra el crimen del Comisario Hagan, en la que murieron varios jefes de la Pandilla Colmena.",
                    [0xdc9628a2e5dccd50UL] = "AYUDA",
                    [0xdead4285f0b5615aUL] = "Nel. Nunca volveré a volar... máh vale rendirme y... [gruñe incomprensible].",
                    [0xdf5bab3f13c23da7UL] = "La comisaría 9 fue atacada hoy por la infame Pandilla Colmena. Su líder, conocida solo como Balista, es la reina del crimen desorganizado de nuestra ciudad.",
                    [0xe09dda4e4d949d9dUL] = "¡Además, quien me traiga al comisario, vivo o muerto, se librará de más violencia!",
                    [0xe2a689e0ef6356deUL] = "¿Q-qué demonios está PASANDO ahí fuera?",
                    [0xe2b3e921c2eb78c8UL] = "¡Eh, eres ese prisionero! ¿Cómo demonios sobreviviste? Da igual. Veo que no eres amigo de la Pandilla Colmena. Ayudémonos.",
                    [0xe36d733447235e46UL] = "Presentador",
                    [0xe4d737b422a42442UL] = "¿Pero por qué parar ahora cuando me estoy DIVIRTIENDO TANTO?",
                    [0xe62825a3f17a8e22UL] = "¡Sí, sí! ¡Baja la voz!",
                    [0xe63446bb533998e4UL] = "¡B-Balista!",
                    [0xe9bb19c6c77ce918UL] = "NO",
                    [0xeb6ea4fbdae67a8dUL] = "BALISTA\r\n  ES\r\nREINA",
                    [0xee11f81195a12305UL] = "¿Y matáis a esa loca por mí, vale?",
                    [0xf0656dbb5ab6cab8UL] = "Claro, señora. ¿Quién?",
                    [0xf0a8e2712d23a8b6UL] = "Última hora: Por orden del alcalde, varias unidades de MetroLaw han sido desplegadas para lidiar con los terroristas que tomaron el control de la comisaría de la Comisaría 9 esta noche.",
                    [0xf24946686c8545c2UL] = "No se rinden, ¿verdad?\r\nQuizá es que no saben cómo.",
                    [0xf563e820c21015beUL] = "Ciudad Soleada, 20XX\r\n\r\n",
                    [0xf5aeb95b33b40b2eUL] = "Supongo que tienes razón Frank... Es importante tener principios.",
                    [0xfe1e16ae5a0d8fdbUL] = "¿Por qué McBride trajo a esos luchadores renegados? MetroLaw los atrapará al final, no tiene sentido resistirse.",
                },
                ["ru"] = new()
                {
                    [0x036a7ec59a2378aeUL] = "Понял, Королева Би.",
                    [0x04288307a2f02760UL] = "Здравствуйте. Хочу сообщить, где находится один печально известный МАССОВЫЙ УБИЙЦА.",
                    [0x0635c55daced5862UL] = "Не собираюсь торчать тут всю ночь!",
                    [0x0e8727e75f2dc91eUL] = "Ты не трогать Королеву Балисту!",
                    [0x0f5797910f6e4222UL] = "Йиии-хааа!!!",
                    [0x11102a388b0c488aUL] = "Я.",
                    [0x1822d75d4c4b2a19UL] = "ПОЩАДА",
                    [0x18e6bef70932509cUL] = "Наблюдатель",
                    [0x1ed278cd898a56f2UL] = "А тепер жду, когда эти бандиты вернутся и добьют меня. Бежать больше нет шил. Одно за другим...",
                    [0x1f203f4e59f5cd8dUL] = "Ну и люди нынче...",
                    [0x1f5b7e573cbf4c01UL] = "Вуух! Классный выстрел, Королева Би!",
                    [0x291202ff73e9e072UL] = "Мэр кратко прокомментировал атаку, назвав ее «крайне несправедливой». Мы будем вести прямой эфир по мере развития событий!",
                    [0x29582d73906f8c40UL] = "Но борьба Порядка и Хаоса еще не решена. Чаша весов качнется, и наши герои снова и снова будут возвращаться в Санни-Сити.",
                    [0x29b4fe2dbb57ef6aUL] = "ЖИЗНЬ ЗА БАЛИСТУУУ!!!",
                    [0x2c9e88d31ec5c7d3UL] = "Метрокоп",
                    [0x2cadd26834d97180UL] = "Не дайте им уйти! Сделайте что-нибудь!",
                    [0x344caa065b4fa30bUL] = "Эй, Фрэнк, одолжи бакс? Хочу газировку из автомата.",
                    [0x345852fa00e98d27UL] = "КОРОЛЕВА",
                    [0x3567f1bf42f27991UL] = "Эй, вы те пленники! Как вы выжили? Неважно. Вижу, вы не друзья Банде Улья. Давайте помогать друг другу.",
                    [0x3626754b9f4fce11UL] = "О, ты еще жив! Залезай!",
                    [0x39b52944cab631faUL] = "Эй, БЕРЕГИСЬ!",
                    [0x3a224d0ee5a8c249UL] = "Кровь! Кровь во имя БАЛИСТЫ!",
                    [0x3a9ff2ee65fcda1eUL] = "БАНДА УЛЬЯ\r\n РУЛИТ!",
                    [0x3dbe25089691de83UL] = "Не волнуйтешь. Я тверд как шкала. И ЛЕТАТЬ буду как шкала, фот увидите.",
                    [0x40cc3f8a39491e51UL] = "Она жива! ЖИВА! Запрыгивайте на борт, парни!",
                    [0x40fedf513f4bf84fUL] = "БЛОК ЗАДЕРЖАНИЯ А",
                    [0x431202ac48344bf4UL] = "Сегодня есть лишь один закон: делай то, что велит тебе Ненависть!",
                    [0x43f92a5c402137ddUL] = "Их слишком... слишком много!",
                    [0x44cc3f3f7d3fe1e0UL] = "Хоть электричество вернулось... но что за чертовщина с камерами?",
                    [0x45112e69a0ede541UL] = "Тут есть пилот, такой же пленник. Он в блоке D. Если кто и вытащит вас отсюда, то он. Я доведу вас до него — но сначала помогите убить Балисту.",
                    [0x46633bc8a3feeadaUL] = "Черт! Что-то не так ш двигателями. Какой болван их делал? Дайте минуту под капот заглянуть...",
                    [0x4777cc942d9250faUL] = "Скажи своим людям расслабиться, детектив. Дальше мы сами.",
                    [0x48f915a5bbed5545UL] = "Странный шум... Не обращу внимания.",
                    [0x4cc55697b6b10e11UL] = "Вы так легко от меня не избавитесь, любители копов!",
                    [0x4cdedc0731675745UL] = "Дело не в ЭТОМ! Дело в... ПРИНЦИПАХ! Что будет с Бандой Улья, если мы начнем ПЛАТИТЬ за вещи?",
                    [0x4df8d1bea7423792UL] = "Купить газировку? КУПИТЬ газировку?! Ты БАНДИТ! У тебя есть БИТА! Просто РАЗБЕЙ эту чертову штуку!",
                    [0x4e52106b24fc9771UL] = "Ладно, вы меня убедили. Дафайте улитаем отшюда!",
                    [0x4fea2fa39f3b3823UL] = "Так им и надо! Не знаю, что задумал Макбрайд, но он хороший коп. Таких в городе почти не осталось...",
                    [0x52a5a79ed1d29c03UL] = "Многие считают сегодняшние события доказательством устарелости обычной полиции и того, что полная приватизация — будущее охраны порядка.",
                    [0x5391db195f195110UL] = "Мягкая посадка, ущитывая обштоятельштва!",
                    [0x54b686163fa4490fUL] = "РУХААААРРР ХУАРРРР!",
                    [0x5954a097af2969f2UL] = "...ЧРЕЗВЫЧАЙКА!!! Покинуть судно!",
                    [0x5a7b270b6fc84783UL] = "Спасибо за помощь. Вам лучше валить отсюда. Подальше от Санни-Сити.",
                    [0x5dc60337c07f4fe1UL] = "Санни-Сити, 20XX\r\n\r\n9-й участок",
                    [0x5e55eaeb18d2b7c8UL] = "БАНДА\r\nУЛЬЯ\r\nРУЛИТ",
                    [0x60cc6f21806e3e1cUL] = "Мфггллл мфвррр! МФВРРРР!",
                    [0x620282fb56b61254UL] = "Ооо... Не знаю, это столько возни... Проще просто...",
                    [0x65d92816d864926eUL] = "Всем моим воинам, верным берсеркам: раздавите последние очаги сопротивления! Принесите мне голову комиссара Хагана!",
                    [0x66d57fd83ba780ceUL] = "Хватит! НИКТО не войдет! Как бы ни УМОЛЯЛИ!",
                    [0x6b2c32be2d6e8929UL] = "Убейте и пленников! Бойцов нам хватает!",
                    [0x6d1da39229b50eb2UL] = "Ты слышал даму, легавый. Пора баиньки!",
                    [0x6e2d3cb39ba594cbUL] = "Вы, УБЛЮДКИ! Вам это с рук не сойдет!",
                    [0x6f48c5680a6578a8UL] = "Шевелись, задница!",
                    [0x6ffcc22b3a80afd2UL] = "Помогите! Оно за мной!",
                    [0x7032c1ee00e8c277UL] = "Джефф",
                    [0x70818f5012b2a6b9UL] = "Так, пофмотрим. Я бы швой шамолет фзял, но... и это шойдет. Ешли найду зажигание. А, фот оно.",
                    [0x70897260e656a02cUL] = "БЛОК",
                    [0x72a8dd799de66b83UL] = "ВЫХОД",
                    [0x74d1004c33a4cf82UL] = "Эта штука штарая даже по моим меркам... Куда эта деталь? Нет, не так...",
                    [0x76593c4f11889014UL] = "Ну то есть, какой шмышл, ешли они могут прочто... хм... это что...",
                    [0x76bae89ee56047a0UL] = "Спаси нас Боже — это Банда Улья!",
                    [0x794b42e6e43d51acUL] = "Неа.",
                    [0x80dc943a46520f6cUL] = "Эй, шеф! Хочу свой звонок!",
                    [0x87ee43f95113b100UL] = "УБЕЙ\r\n  ВСЕХ\r\nКОПОВ",
                    [0x8ac3573c90cfbc94UL] = "Так ты натравишь моих людей на меня?! Ах ты злобная, вонючая, кровожадная...",
                    [0x8b374962aea1e30eUL] = "Ха! Не дождешься!",
                    [0x8b3bc239dedf1bc0UL] = "Черт, они идут! Слушайте. За дверью позади вас есть лифт. Я попробую найти другой путь наверх. Встретимся там — надеюсь.",
                    [0x8b3bd9f00d1c3605UL] = "Нет! Как вы вошли? ПОМОГИТЕ!!",
                    [0x8b8b89dc8de8ecf6UL] = "Убейте их.",
                    [0x8bb41de9553af736UL] = "А пока что сказать, кроме как:\r\nОтлично сыграно, дамы и господа.",
                    [0x8e781aceec208dfeUL] = "Говорит Балиста. Участок теперь под контролем Банды Улья. Все выходы перекрыты. Сбежать невозможно.",
                    [0x8eb45aba1a7af43fUL] = "...с ухудшением погоды и снегопадом на выходных.",
                    [0x8eda0d484d2b9b1aUL] = "Прибереги отмазки для босса, идиот!",
                    [0x919ac2597112e633UL] = "Никто не выйдет, по приказу Балисты!",
                    [0x921185c061452504UL] = "Умри! По приказу Балисты!",
                    [0x9445dc6be5a3ee7dUL] = "Не знаю. Хотел допросить или типа того. Или просто насолить этим корпоративным слизнякам.",
                    [0x993a2f48484a41e2UL] = "ЭЙ! У вас вообще есть уважение к закону?!",
                    [0xa3e0bd0a4c2d32faUL] = "Ты... ты... да я тебя...!",
                    [0xa5a988f92c1e63c4UL] = "Мертв?!\r\n\r\nКто бы ты ни был, ты разозлил Банду Улья!",
                    [0xa5e7abbb835df100UL] = "БАНДА УЛЬЯ",
                    [0xa63fb33072e54399UL] = "Незнакомка",
                    [0xa6584a89b26fe7b3UL] = "УБЕЙ",
                    [0xa6c6d892eb95e471UL] = "Не дайте объектам сбежать!",
                    [0xab522c636a0e6128UL] = "Не поверишь, как я выжил. Расскажу потом!",
                    [0xafae86a2590e4b00UL] = "Откротку пришлете, а?",
                    [0xafc7d444ab3a616bUL] = "Ешли ищете мое пиво, его нет. Эти копы ш... ш... забрали его, когда повязали меня. Забрали мои крылья, гады!",
                    [0xb212b8ea4802f71aUL] = "ПОРАЖЕНИЕ\r\nПилот погиб!",
                    [0xb7d3d2d176763a19UL] = "Кстати, я Джефф. Знаешь, это может быть началом чего-то прекрасного...",
                    [0xbb5a28cd54f65e38UL] = "Трансляцию спонсирует МетроКорп: Светлое будущее для Санни-Сити. Спокойной ночи!",
                    [0xbb6a540c1ec0e4f4UL] = "Армия фанатичных головорезов Балисты быстро захватила участок и забаррикадировалась внутри! Неизвестно, выжил ли кто-то в этой резне!",
                    [0xbcb3cc0bf22360bdUL] = "Говорит Балиста! Трус Хаган должен сдаться!",
                    [0xbce92351bca42cf8UL] = "Мэр считает ваш отдел... НЕДОСТАТОЧНЫМ для такой ситуации. Предоставьте это профессионалам.",
                    [0xbd1b53ade13daa4dUL] = "Задержите их, пока я фозьусь ш этой штукой!",
                    [0xbdd49e2f3d6dd1d1UL] = "Думаю, пора отдохнуть. Миг покоя, где-то за теми темными холмами.",
                    [0xc09bbd3d2f3fdbccUL] = "Вы, наемные подонки! Я просил подкрепление — КОПОВ, а не кучку наемников-отморозков!",
                    [0xc232981f08e5d7beUL] = "Я прекрасно это ЗНАЮ, детектив. Спокойной ночи.",
                    [0xc2df6869edc67547UL] = "УБЕЙТЕ\r\nИХ\r\nВСЕХ",
                    [0xc5ad69595973c5cbUL] = "АНАРХИЯ",
                    [0xc74a88131e6a22dfUL] = "Хм. Первый двигатель готов, а фторой надо подшаманить. Задержите их еще немного, парни!",
                    [0xc8dea6adab5b0254UL] = "ПОВИНУЙСЯ",
                    [0xc96a323fc267e0feUL] = "Давай, сваливаем отсюда!",
                    [0xcd2a719214a4f9b6UL] = "Балиста",
                    [0xcf18e1924041e938UL] = "Приказываю опечатать все выходы. Никто не войдет и не выйдет. Навещу-ка Комиссара.",
                    [0xd0c865f0a840ceb5UL] = "БЕЗ\r\nПОЩАДЫ",
                    [0xd0ed97895f85a908UL] = "Что, например? Мы и так по ним стреляем. И Чистильщики кончились.",
                    [0xd234a886d21a0080UL] = "Сдавайся, Балиста! Хаган мертв — ты получила, что хотела!",
                    [0xd844e8b6c449a9dfUL] = "Альфа танго — зета фокстрот. Выпускайте Чистильщиков.",
                    [0xdab28176b0d9658fUL] = "РУЛИТ",
                    [0xdb046f5df26c80aeUL] = "Нападение, вероятно, было местью за недавнюю кампанию комиссара Хагана, в ходе которой погибли несколько главарей Банды Улья.",
                    [0xdc9628a2e5dccd50UL] = "ПОМОГИТЕ",
                    [0xdead4285f0b5615aUL] = "Неа. Больше не летать... проще шдаться и... [бормочет].",
                    [0xdf5bab3f13c23da7UL] = "Сегодня участок 9-го округа атакован печально известной Бандой Улья. Ее лидер, женщина, известная лишь как Балиста — самопровозглашенная королева городского беспредела.",
                    [0xe09dda4e4d949d9dUL] = "Более того, каждый, кто приведет комиссара — живым или мертвым — избежит дальнейшего насилия!",
                    [0xe2a689e0ef6356deUL] = "Ч-что за черт ТУТ происходит?",
                    [0xe2b3e921c2eb78c8UL] = "Эй, ты тот пленник! Как ты выжил? Неважно. Вижу, ты не друг Банде Улья. Давай помогать друг другу.",
                    [0xe36d733447235e46UL] = "Диктор",
                    [0xe4d737b422a42442UL] = "А зачем останавливаться, когда так ВЕСЕЛО?",
                    [0xe62825a3f17a8e22UL] = "Да, да. Потише!",
                    [0xe63446bb533998e4UL] = "Б-Балиста!",
                    [0xe9bb19c6c77ce918UL] = "НЕТ",
                    [0xeb6ea4fbdae67a8dUL] = "БАЛИСТА\r\n  ЭТО\r\nКОРОЛЕВА",
                    [0xee11f81195a12305UL] = "И убейте для меня эту чокнутую, ладно?",
                    [0xf0656dbb5ab6cab8UL] = "Конечно, мэм. Кто?",
                    [0xf0a8e2712d23a8b6UL] = "Срочная новость: по приказу мэра на борьбу с террористами, захватившими 9-й участок, направлены отряды MetroLaw.",
                    [0xf24946686c8545c2UL] = "Они не сдаются, да?\r\nМожет, просто не умеют.",
                    [0xf563e820c21015beUL] = "Санни-Сити, 20XX\r\n\r\n",
                    [0xf5aeb95b33b40b2eUL] = "Наверно, ты прав, Фрэнк... Важно иметь принципы.",
                    [0xfe1e16ae5a0d8fdbUL] = "Зачем Макбрайд привел этих отморозков? MetroLaw их все равно достанет — нет смысла сопротивляться.",
                },
            },
            ["363e25b5-c239-4a2e-bfb8-837535807f18"] = new()
            {
                ["es"] = new()
                {
                    [0x00c828920feb30a9UL] = "No pareces nazi, ¿cómo demonios saliste vivo?",
                    [0x00f894c753526ecaUL] = "Ah, hijos míos... habéis matado al pobre Kriegbär #2.",
                    [0x04ea71f543f7a181UL] = "¡Pero también mi mayor ERROR! ¡Es hora de rectificarlo! ¡Frau Sturmbannführer! ¡Traédmelos!",
                    [0x130cb8e004b1746fUL] = "O Tannenbaum, o Tannenbaum,\nwie treu sind deine Blätter!",
                    [0x16c94d4cdbfbd83aUL] = "¡Nein, nein, nein! ¡Otra vez tarde!",
                    [0x1ffaba68dba5eb7dUL] = "No importa, me lo cuentas luego. ¡Mis órdenes son sacaros de aquí cagando leches!",
                    [0x263ef99ee3dd3bdfUL] = "(¡Y pronto el propio Führer se acobardará ante Fritzliebe! ¡Ja-ja!)",
                    [0x266ca9e1237fd940UL] = "¿Qué es eso, doctor?",
                    [0x3702712331c60bbbUL] = "¡NEIN! ¡Du darfst den Weihnachtsbaum nicht zerstören!",
                    [0x37d4da79f91ea69dUL] = "...¡pero también tengo muchos avances MECHANISCHE que mostraros!",
                    [0x399d69478283bf0aUL] = "¡Ah, pobre Kriegbär #2! Era una de mis criaturas favoritas. Oh, bueno... ¡Admito la derrota! ¡Entrad y discutamos los términos de mi rendición!",
                    [0x3d0b9534cd0767daUL] = "Du grünst nicht nur zur Sommerzeit,\nNein auch im Winter, wenn es schneit!",
                    [0x3f57a8067643aaf1UL] = "¡¡¡Attentaten!!!",
                    [0x46ee9a6b83e2eaf5UL] = "¡Otra vez, desde arriba! ¡Y con más sentimiento esta vez!",
                    [0x4b729df370265d0aUL] = "¡Pero también mi mayor ERROR! ¡Es hora de rectificarlo! ¡Frau Sturmbannführer! ¡Traedme al espécimen!",
                    [0x4bd699fb74d17592UL] = "¡Das ist unfair!",
                    [0x50b1af47c674d007UL] = "Buenas noches, Dr. Fritzliebe! ¿Cómo va el proyecto Überkämpfer?",
                    [0x537f76c41d40d6cbUL] = "¡Mein Gott! ¡Detenedlos!",
                    [0x5712908027cd5023UL] = "No parecéis nazis, ¿cómo demonios salisteis vivos?",
                    [0x5767d170e5d4e177UL] = "¡He dicho, HEIL HITLER!",
                    [0x593a7092b87f94baUL] = "¡Verdammt! ¡Un ataque aéreo aliado!",
                    [0x5b1a6ebf6ea7465eUL] = "¡Excelentemente, Herr Sturmbannführer! ¡Los prisioneros están respondiendo extremadamente bien a la fórmula! ¡Pronto el Führer tendrá su ejército imparable!",
                    [0x6330a806d40f3cdcUL] = "¡¡¡HNNNARRRRRRRHHH!!!",
                    [0x63b1bc586efa968cUL] = "BIOCHEMIE es mi especialidad, es cierto...",
                    [0x6f47bc553da9b8e5UL] = "*cof* ¡Arrrrrgh... Schweinhunden! ¡Me habéis matado... pero no escaparéis vivos de aquí!",
                    [0x6ff7c93100bf1649UL] = "¡Tendré que desmontaros y empezar de nuevo. ¡Y esta vez seréis perfectos!",
                    [0x7c20e94fb4650a48UL] = "Kriegbär #2",
                    [0x81e08fcf3b26b2c0UL] = "¡Ah, hijo mío! ¡Has llegado tan lejos! ¡Qué orgulloso estoy! ¡Eres realmente mi mayor TRIUNFO científico!",
                    [0x829963066c214aaaUL] = "Dr. Fritzliebe",
                    [0x8ea04a9910d7a8abUL] = "¡¡¡RARRRRRRRRH!!!",
                    [0x99f616758a5083a7UL] = "¡Ja! ¡Ya veremos!",
                    [0x9e76ca2b1b590009UL] = "¡Hm! ¿El Kriegbär ha escapado? ¡Eso no augura nada bueno para ti, Lieblings!",
                    [0x9f031c4016299ccaUL] = "Si lo que he oído es cierto, podríais ser justo lo que necesitamos para ganar esta guerra...",
                    [0xa00cfe8c3f89d67eUL] = "Oficial SS",
                    [0xa0af763a31a874f1UL] = "Ahí va, chicos. Misión cumplida.",
                    [0xab049533d0c82bb7UL] = "¡HEIL HITLER!",
                    [0xb20893ef0887644aUL] = "¡Insolentes!",
                    [0xbe70d440b4b5571fUL] = "¡Muere ahora!",
                    [0xc016c3d70a417178UL] = "¡Hm! ¿El Kriegbär ha escapado? ¡Eso no augura nada bueno para ti, amigo mío!",
                    [0xc7a4c28cb3b0df2eUL] = "¡Es hora de rectificar ese error! ¡Os desmontaré y empezaré de nuevo. Y el próximo modelo será mejor. ¡OBEDECERÁ!",
                    [0xcdd6675c1b199d86UL] = "¡Alguien sale, señor!",
                    [0xce98a25209ef4e14UL] = "Coro",
                    [0xd1463da2413c9109UL] = "Castillo Sonnenfreude\nEn algún lugar de Austria\nDiciembre de 1943",
                    [0xd14f14ca876a1d5dUL] = "¡Ah, niños! ¡Habéis llegado tan lejos! ¡Qué orgulloso estoy! ¡Sois realmente mi mayor TRIUNFO científico!",
                    [0xdbf2762283f9e73dUL] = "¡No temáis! ¡Mi sistema antiaéreo se encargará de ellos en breve!",
                    [0xe81aa415f0160f15UL] = "Aun así... estos viejos sótanos están en mal estado. ¡¡Raus!!",
                    [0xf499c110f6abe42bUL] = "¡Sois mi mayor triunfo... pero también mi mayor error!",
                    [0xf682ec890cd8dea9UL] = "¡Verdammt! ¿Wo ist der Aufzug?",
                },
                ["ru"] = new()
                {
                    [0x00c828920feb30a9UL] = "Ты не похож на нациста — как ты выжил?",
                    [0x00f894c753526ecaUL] = "Ах, дети мои... вы убили бедного Кригбэра #2.",
                    [0x04ea71f543f7a181UL] = "Но и моя величайшая ОШИБКА! Пора исправить! Фрау штурмбаннфюрер! Приведите их ко мне!",
                    [0x130cb8e004b1746fUL] = "O Tannenbaum, o Tannenbaum,\nwie treu sind deine Blätter!",
                    [0x16c94d4cdbfbd83aUL] = "Нет, нет, нет! Опять опаздываете!",
                    [0x1ffaba68dba5eb7dUL] = "Неважно, потом расскажешь. Мой приказ — вытащить вас отсюда к чертям!",
                    [0x263ef99ee3dd3bdfUL] = "(И скоро сам фюрер будет дрожать перед Фрицлибе! Ха-ха!)",
                    [0x266ca9e1237fd940UL] = "Что это, доктор?",
                    [0x3702712331c60bbbUL] = "НЕТ! Не смей трогать рождественскую елку!",
                    [0x37d4da79f91ea69dUL] = "...но у меня есть и много МЕХАНИЧЕСКИХ достижений!",
                    [0x399d69478283bf0aUL] = "Ах, бедный Кригбэр #2! Он был одним из моих любимцев. Ну ладно... Признаю поражение! Входите, обсудим условия моей капитуляции!",
                    [0x3d0b9534cd0767daUL] = "Du grünst nicht nur zur Sommerzeit,\nNein auch im Winter, wenn es schneit!",
                    [0x3f57a8067643aaf1UL] = "Покушение!!!",
                    [0x46ee9a6b83e2eaf5UL] = "Снова, с начала! И с большим чувством!",
                    [0x4b729df370265d0aUL] = "Но и моя величайшая ОШИБКА! Пора исправить! Фрау штурмбаннфюрер! Приведите образец!",
                    [0x4bd699fb74d17592UL] = "Это несправедливо!",
                    [0x50b1af47c674d007UL] = "Добрый вечер, доктор Фрицлибе! Как продвигается проект Уберкемпфер?",
                    [0x537f76c41d40d6cbUL] = "Боже мой! Остановите их!",
                    [0x5712908027cd5023UL] = "Вы не похожи на нацистов — как вы выжили?",
                    [0x5767d170e5d4e177UL] = "Я сказал, ХАЙЛЬ ГИТЛЕР!",
                    [0x593a7092b87f94baUL] = "Черт! Воздушный налет союзников!",
                    [0x5b1a6ebf6ea7465eUL] = "Превосходно, герр штурмбаннфюрер! Пленники отлично реагируют на формулу. Скоро у фюрера будет непобедимая армия!",
                    [0x6330a806d40f3cdcUL] = "ХНННАРРРР!!!",
                    [0x63b1bc586efa968cUL] = "БИОХИМИЯ — моя специальность, это правда...",
                    [0x6f47bc553da9b8e5UL] = "*кашляет* Аррргх... Швайнхунде! Вы убили меня... но живыми вы отсюда не уйдете!",
                    [0x6ff7c93100bf1649UL] = "Я разберу вас и начну заново. В этот раз вы будете идеальны!",
                    [0x7c20e94fb4650a48UL] = "Кригбэр #2",
                    [0x81e08fcf3b26b2c0UL] = "Ах, дитя мое! Ты зашло так далеко. Как я горд! Ты — мой величайший научный ТРИУМФ!",
                    [0x829963066c214aaaUL] = "Д-р Фрицлибе",
                    [0x8ea04a9910d7a8abUL] = "РРРРРРРР!!!",
                    [0x99f616758a5083a7UL] = "Ха! Посмотрим!",
                    [0x9e76ca2b1b590009UL] = "Хм! Кригбэр сбежал? Плохой знак для тебя, любимчик!",
                    [0x9f031c4016299ccaUL] = "Если то, что я слышал, правда, вы как раз то, что нужно, чтобы выиграть войну...",
                    [0xa00cfe8c3f89d67eUL] = "Офицер СС",
                    [0xa0af763a31a874f1UL] = "Вот и все, парни. Миссия выполнена.",
                    [0xab049533d0c82bb7UL] = "ХАЙЛЬ ГИТЛЕР!",
                    [0xb20893ef0887644aUL] = "Наглецы!",
                    [0xbe70d440b4b5571fUL] = "Умри!",
                    [0xc016c3d70a417178UL] = "Хм! Кригбэр сбежал? Это плохой знак для тебя, мой друг!",
                    [0xc7a4c28cb3b0df2eUL] = "Пришло время исправить ошибку! Я разберу вас и начну заново. Следующая модель будет лучше. Она будет ПОВИНОВАТЬСЯ.",
                    [0xcdd6675c1b199d86UL] = "Кто-то выходит, сэр!",
                    [0xce98a25209ef4e14UL] = "Хор",
                    [0xd1463da2413c9109UL] = "Замок Зонненфройде\nГде-то в Австрии\nДекабрь 1943",
                    [0xd14f14ca876a1d5dUL] = "Ах, дети! Вы зашли так далеко. Как я горд! Вы — мой величайший научный ТРИУМФ!",
                    [0xdbf2762283f9e73dUL] = "Не бойтесь! Моя зенитная система скоро с ними разберется!",
                    [0xe81aa415f0160f15UL] = "И все же... эти старые подвалы в плохом состоянии. Вон!!",
                    [0xf499c110f6abe42bUL] = "Вы — мой величайший триумф... но и моя величайшая ошибка!",
                    [0xf682ec890cd8dea9UL] = "Черт! Где лифт?",
                },
            },
            ["52ac9704-61c1-4227-bfd4-9196b81d4f7c"] = new()
            {
                ["es"] = new()
                {
                    [0x63e3b460a0674fcaUL] = "¡El Equipo Azul está que ARDE esta noche! ¡Pero veamos cómo se las arreglan con fuego de verdad! ¡Es hora de...",
