            ["9981018a-c343-442a-983e-719321c4da59"] = new()
            {
                ["es"] = new()
                {
                    [0x01051dfa0e811b17UL] = "Recibido alfa 3. Todas las unidades desplegadas, nos acercamos al objetivo.",
                    [0x01d074f6960b333eUL] = "¿Un poco desorientado? ¡No te preocupes!",
                    [0x03975ae59704af11UL] = "¡Tres!",
                    [0x1263fd91b03b820dUL] = "¡Ha llegado el momento, damas y caballeros, del esperado final de temporada de Superfighters Live!",
                    [0x159daaac4f56d7e3UL] = "¡¡¡NO voy a volver a la Hora Infantil!!!",
                    [0x18bb1c8f44f2b01dUL] = "¡Recuerda, son ellos o nosotros!",
                    [0x1a24dee897c52d65UL] = "¡Parad las rotativas!",
                    [0x1f08e947dd01d281UL] = "¡Je je!",
                    [0x21ca3b0f1921b2f0UL] = "¡No podéis tratarnos así!",
                    [0x23f457d3dc9522ebUL] = "¡Dos!",
                    [0x2548fccef3d6e3f0UL] = "¡Buen trabajo ahí fuera! ¡Vaya forma de encargarte de esos macarras!",
                    [0x2a75dd56ca6fef83UL] = "Je je je...",
                    [0x2b030ca41081902aUL] = "Bromista",
