                ["es"] = new()
                {
                    [0x355f12fe77de5784UL] = "¡Esto no ha terminado, maderos! ¡Estáis acabados! ¡MetroLaw es el futuro!",
                    [0x417cd86cc0ca6c17UL] = "De lo contrario, se les cobrará por completo cualquier daño adicional a edificios de valor cultural durante su arresto...",
                    [0x425ee91164382a0aUL] = "Sus hombres deberían aprender a no apuntar con sus armas a un compañero. Somos los detectives McBride y Santana, del SCPD. Nosotros nos encargamos.",
                    [0x466aae9dccce80d5UL] = "Ah, pero esta sigue siendo una comisaría del SCPD. Lo siento, oficial. Si quiere su premio, tendrá que seguir los canales adecuados.",
                    [0x8050359da2050ad6UL] = "Ayúdame a esposarlos, Santana. Nos vamos a la central.",
                    [0x8422c9c595e7687cUL] = "¡P-pero QUÉ!",
                    [0xa42e1ea0d7d127c8UL] = "Muy bien, chicos, esposen rápido a estos sacos de carne antes de que despierten.",
                    [0xb9158363e1220395UL] = "¡Largo, aficionados! Estos son los sacos de carne que volaron la estación de TV. Son propiedad del gobierno.",
